*/
function evaluateEvent({api, event}) {
	return {
		eventName: "SIDEBAR#TEAMS_DROPDOWN_ITEM_CLICKED",
		eventPayload: {
			dropdownId: event.payload.item.id,
			providerId: api.state.teamsProviderId,
			providerAppId: api.state.teamsProviderApplicationId
		}
	};
}

